const CEILINGS = {
  'z-ai/glm-5.3-flash': 131072,
  'anthropic/claude-sonnet-5': 128000,
};
const DEFAULT_CEILING = 32768;
const REQUIRED = ['stepName', 'model', 'system', 'user', 'maxTokens'];

return $input.all().map((item, i) => {
  const j = item.json;
  for (const f of REQUIRED) {
    if (j[f] === undefined || j[f] === null || j[f] === '') {
      throw new Error(`missing required field '${f}' on item ${i} (stepName=${j.stepName})`);
    }
  }
  return {
    json: {
      ...j,
      chunkIndex: j.chunkIndex === undefined ? i : j.chunkIndex,
      temperature: j.temperature === undefined ? 0.3 : j.temperature,
      attempt: 1,
      ceiling: CEILINGS[j.model] || DEFAULT_CEILING,
      baseMaxTokens: j.maxTokens,
    },
  };
});

const CANON = ['general', 'insights', 'qa', 'tools', 'links', 'decisions'];

function parseSections(md) {
  const re = /^#{1,3}[ \t]+([a-z]+)[ \t]*$/gm;
  const found = []; let m;
  while ((m = re.exec(md)) !== null) found.push(m[1]);
  return found.filter((s) => CANON.includes(s));
}

// Unfiltered heading extraction for signal.reduce: the parser's parse_extracted_signal
// raises on ANY non-canonical heading, so the validator must see every heading
// (including non-canonical ones) rather than silently discarding them.
function parseAllHeadingSlugs(md) {
  const re = /^#{1,3}[ \t]+([a-z]+)[ \t]*$/gm;
  const found = []; let m;
  while ((m = re.exec(md)) !== null) found.push(m[1]);
  return found;
}

function isFencedWhole(text) {
  // Finding A: parser._strip_fenced_code runs BEFORE section splitting, so a
  // reducer/map response wrapped whole in a fence still looks structurally
  // valid to a naive heading scan here, but the parser strips the fence first
  // and then finds zero '##' sections. Reject rather than unwrap, so the
  // retry ladder makes the model comply instead of us silently laundering
  // its output.
  const t = text.trim();
  return /^```[^\n]*\n[\s\S]*```$/.test(t);
}

function structureOk(expect, text) {
  if (!expect || expect === 'none') return true;
  if (expect === 'prep.chunk') {
    // Mirrors community_brain.ingestion.parser._SEGMENT_HEADER_RE: the parser
    // requires topic/speakers/keywords/summary, in that exact order, or it
    // silently drops the segment. Validate the same schema here so a
    // malformed header fails fast instead of losing content at ingestion.
    const SEGMENT_HEADER_RE = /<!--SEGMENT\s*\ntopic:\s*.*?\nspeakers:\s*.*?\nkeywords:\s*.*?\nsummary:\s*.*?\n-->/gs;
    const opens = (text.match(/<!--SEGMENT/g) || []).length;
    const headers = [...text.matchAll(SEGMENT_HEADER_RE)];
    if (!(opens > 0 && headers.length === opens)) return false;
    const MIN_BODY_CHARS = 50;
    for (let i = 0; i < headers.length; i++) {
      const bodyStart = headers[i].index + headers[i][0].length;
      const bodyEnd = i + 1 < headers.length ? headers[i + 1].index : text.length;
      const body = text.slice(bodyStart, bodyEnd).replace(/\s/g, '');
      if (body.length < MIN_BODY_CHARS) return false;
    }
    return true;
  }
  if (expect === 'signal.map') return !isFencedWhole(text) && parseSections(text).length > 0;
  if (expect === 'signal.reduce') {
    if (isFencedWhole(text)) return false;
    // Require EXACTLY the six canonical slugs -- no extras, no dupes, no gaps.
    // The parser raises ValueError on any non-canonical heading, so a document
    // with all six plus a stray seventh must fail here, not pass and break /ingest.
    const found = parseAllHeadingSlugs(text);
    if (found.length !== CANON.length) return false;
    return CANON.every((s) => found.includes(s));
  }
  if (expect === 'post.section') {
    return !/^\s*#{1,6}\s/m.test(text) && !/\*\*/.test(text) && !/^\s*[-*]\s+/m.test(text);
  }
  return true;
}

const requests = $('Code: Normalize').all().map((i) => i.json);

return $input.all().map((item, idx) => {
  const req = requests[idx] || requests[0];
  const body = item.json || {};
  const choice = (body.choices || [])[0] || {};
  const usage = body.usage || {};
  const details = usage.completion_tokens_details || {};
  const text = (choice.message && choice.message.content) || '';
  const finishReason = choice.finish_reason || null;

  let failureKind = null;
  if (body.error || (!body.choices && !text)) {
    failureKind = 'api_error';
  } else if (text.trim() === '') {
    failureKind = 'reasoning_burn';
  } else if (finishReason !== 'stop') {
    failureKind = 'content_truncated';
  } else if (!structureOk(req.expect, text)) {
    failureKind = 'structure';
  }

  return {
    json: {
      ...req,
      chunkIndex: req.chunkIndex,
      stepName: req.stepName,
      text,
      ok: failureKind === null,
      failureKind,
      finishReason,
      attempts: req.attempt,
      usage: {
        promptTokens: usage.prompt_tokens || 0,
        completionTokens: usage.completion_tokens || 0,
        reasoningTokens: details.reasoning_tokens || 0,
        cost: usage.cost || 0,
      },
      model: req.model, maxTokens: req.maxTokens, reasoningEffort: req.reasoningEffort,
      temperature: req.temperature, system: req.system, user: req.user,
      ceiling: req.ceiling, expect: req.expect,
      errorMessage: (body.error && body.error.message) || null,
    },
  };
});

const LADDER = { 2: { effort: 'low', factor: 1.5 }, 3: { effort: 'minimal', factor: 2 } };

return $input.all()
  .filter((i) => !i.json.ok && i.json.attempts < 3)
  .map((i) => {
    const j = i.json;
    const nextAttempt = j.attempts + 1;
    const rung = LADDER[nextAttempt];
    const raised = Math.floor(j.baseMaxTokens * rung.factor);
    return {
      json: {
        ...j,
        stepName: j.stepName, model: j.model, system: j.system, user: j.user,
        chunkIndex: j.chunkIndex, temperature: j.temperature, expect: j.expect,
        ceiling: j.ceiling, attempt: nextAttempt,
        reasoningEffort: rung.effort,
        baseMaxTokens: j.baseMaxTokens,
        maxTokens: Math.min(raised, j.ceiling),
      },
    };
  });

