  }
}
const best = new Map();
for (const j of seen) {
  const prev = best.get(j.chunkIndex);
  if (!prev || (j.ok && !prev.ok) || (j.ok === prev.ok && j.attempts > prev.attempts)) {
    best.set(j.chunkIndex, j);
  }
}
return [...best.values()].sort((a, b) => a.chunkIndex - b.chunkIndex).map((json) => ({ json }));
